package com.nimbusbill.customer.service;
import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.entity.*; import com.nimbusbill.customer.repository.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service @Transactional public class AiAssistantService{private final CustomerAccessService access;private final CustomerRepository customers;private final PaymentTransactionRepository transactions;private final InvoiceRepository invoices;private final AiQueryAuditRepository audits;public AiAssistantService(CustomerAccessService a,CustomerRepository c,PaymentTransactionRepository t,InvoiceRepository i,AiQueryAuditRepository q){access=a;customers=c;transactions=t;invoices=i;audits=q;}
public AiAssistantResponse ask(AiAssistantRequest r,Authentication auth){if(!access.isAdmin(auth)||r.customerId()!=null)access.require(auth,r.customerId());String q=r.question().toLowerCase();String intent;String answer;List<String> sources=new ArrayList<>();var tx=transactions.findAll().stream().filter(t->r.customerId()==null||t.getCustomer().getId().equals(r.customerId())).toList();var inv=invoices.findAll().stream().filter(i->r.customerId()==null||i.getCustomer().getId().equals(r.customerId())).toList();if(q.contains("overdue")){intent="OVERDUE_INVOICES";var items=inv.stream().filter(i->"OVERDUE".equals(i.getStatus())).toList();answer="There are "+items.size()+" overdue invoices totalling "+items.stream().map(Invoice::getGrandTotal).reduce(BigDecimal.ZERO,BigDecimal::add)+".";sources.add("invoices.status,due_date,grand_total");}else if(q.contains("reject")||q.contains("fail")){intent="TRANSACTION_EXCEPTIONS";long n=tx.stream().filter(t->t.getStatus()==PaymentTransactionStatus.REJECTED||t.getStatus()==PaymentTransactionStatus.FAILED).count();answer=n+" transactions are rejected or failed in the selected scope.";sources.add("payment_transactions.status,failure_reason");}else if(q.contains("revenue")||q.contains("collect")){intent="REVENUE";BigDecimal billed=inv.stream().filter(i->Set.of("ISSUED","OVERDUE","PAID","DISPUTED").contains(i.getStatus())).map(Invoice::getGrandTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal paid=inv.stream().filter(i->"PAID".equals(i.getStatus())).map(Invoice::getGrandTotal).reduce(BigDecimal.ZERO,BigDecimal::add);answer="Invoiced revenue is "+billed+" and collected revenue is "+paid+".";sources.add("invoices.status,grand_total");}else if(q.contains("customer")){intent="CUSTOMERS";long active=customers.findAll().stream().filter(c->c.getStatus()==CustomerStatus.ACTIVE).count();answer="NimbusBill has "+active+" active customers.";sources.add("customers.status");}else{intent="TRANSACTION_SUMMARY";long complete=tx.stream().filter(t->t.getStatus()==PaymentTransactionStatus.COMPLETED).count();answer="The selected scope contains "+tx.size()+" transactions, including "+complete+" completed.";sources.add("payment_transactions.status,customer_id");}AiQueryAudit audit=new AiQueryAudit();audit.setActor(auth==null?"local-admin":auth.getName());audit.setCustomerId(r.customerId());audit.setQuestion(mask(r.question()));audit.setAnswerSummary(answer);audit.setIntent(intent);audits.save(audit);return new AiAssistantResponse(intent,answer,sources,0.95,Instant.now());}private String mask(String text){return text.replaceAll("\\b\\d{8,18}\\b","********");}}
